#!/usr/bin/env python3
import csv,json,os
os.environ.setdefault("MPLCONFIGDIR","/tmp/prefill-capacity-matplotlib")
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parent;OUT=ROOT/'evidence'
rows=json.loads((OUT/'capacity.json').read_text());attempted=[r for r in rows if r['ns3_wall_s'] is not None];success=[r for r in rows if r['strictly_verified']]
host=json.loads((OUT/'initial-host.json').read_text())
lines=['# EP64 prefill capacity observations','', 'This is an actual bounded host-capacity experiment, not a speedup scan. Topology, synthetic routing distribution, application/native semantics and model parameters are fixed in [experiment-plan.md](../experiment-plan.md). Host resource guards were declared before execution.','','## Result and scope','',f"Largest fully verified requested NoBalance scale: **{max((r['requested_assignments'] for r in success if r['mode']=='no-balancing'),default=0):,} assignments**. Simulation completion alone is not counted as success. No OOM claim follows from a timeout or software rejection.",'','| Mode | Requested T / A | Status | ns3 wall s | ns3 peak RSS GiB | Verifier wall s | Verifier peak RSS GiB | Simulated layer µs |','|---|---:|---|---:|---:|---:|---:|---:|']
def fmt(x,d=2):return '—' if x is None else f'{x:,.{d}f}'
for r in rows:
 lines.append(f"| {r['mode']} | {r['requested_tokens']:,} / {r['requested_assignments']:,} | {r['status']} | {fmt(r['ns3_wall_s'])} | {fmt(r['ns3_peak_rss_kib']/1024**2 if r['ns3_peak_rss_kib'] else None,3)} | {fmt(r['verify_wall_s'])} | {fmt(r['verify_peak_rss_kib']/1024**2 if r['verify_peak_rss_kib'] else None,3)} | {fmt(r['layer_latency_ps']/1e6 if r['layer_latency_ps'] else None,6)} |")
lines+=['','The CSV additionally records generation/plan/adapter CPU and wall time/RSS, sampled process-tree RSS, generated tasks/WQEs, expected and observed request TAs, application log rows, actual ns3 event count, raw log sizes and partial-token completion. Missing metrics are unavailable, never zero-filled as successful results. Each stage console/resource trace and raw artifact hashes are in `runs/<case>/`. Complete synthetic raw evidence is losslessly archived per attempted case.','','## Failures, unattempted and unselected cases','']
for r in rows:
 if not r['strictly_verified']:lines.append(f"- **{r['case_id']} — {r['status']}**: {r['reason']}")
lines+=['','## Phase cost and traffic counts','', '| Case | Plan wall s | Plan CPU user+sys s | Adapter wall s | Remote WQEs planned | Request TAs observed | ns3 events executed | Application rows | Native logs MiB |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for r in rows:
 if r['planner_wall_s'] is None:continue
 cpu=r['planner_user_cpu_s']+r['planner_system_cpu_s']
 lines.append(f"| {r['case_id']} | {fmt(r['planner_wall_s'])} | {fmt(cpu,3)} | {fmt(r['adapter_wall_s'])} | {fmt(r['generated_remote_WQEs'],0)} | {fmt(r['actual_target_received_TAs'],0)} | {fmt(r['ns3_executed_events'],0)} | {fmt(r['application_event_rows'],0)} | {fmt(r['raw_native_log_bytes']/1024**2)} |")
lines+=['','NoBalance plan time is baseline plan construction/serialization, **not invocation of the CPU quota solver**. UltraEP plan time includes the actual CPU solver/checker and serialization (including reference preparation/compilation if its cache is cold); the adapter reuses that exact saved plan instead of solving again. Configured planning/reroute nanoseconds are the only planner delays in simulated time. Wall measurement includes 0.5-second exit-poll granularity; user/system CPU times use wait4. Peak RSS is wait4 ru_maxrss; sampled tree RSS sums process RSS and may double-count shared pages. Cgroup memory includes other resident/cache memory. These metrics are deliberately not conflated.','','Transaction count here means **target-received request TAs**, not the count of transaction-engine objects (one per host), and not ACK responses. Generated remote WQEs are case-derived; completed WQEs/TAs and application events are trace-derived. `Simulator::GetEventCount()` is emitted only when `Simulator::Run()` returns. A guard-killed process therefore has no complete ns3 event count even when a partial application CSV exists.','','## Resource curves','', '![Measured host resource curves](resource-curves.png)','','No extrapolated points or speedup curves are shown. Failed/timed-out ns3 points are censored at the protection boundary, not completed runtimes. The per-stage `resource-samples.csv` files retain the complete measured RSS/cgroup/time trajectories.','','## Capacity interpretation and next work','', '- The old 100K-assignment/256MiB guards are software constraints. This experiment distinguishes those from observed host-wall/resource stops. See [native/integer/allocation audit](../SAFETY-AUDIT.md).','- Per-remote-Jetty ACK windows alone require 16KiB each; explicit payload, per-task metadata, packet/events, Python JSON and verifier copies add further cost. No window resizing, pooling, packing, logical payload, protocol edits or verifier optimization was performed.','- 20-bit wire Jetty IDs prohibit the requested 1M assignment case under the current global-task-ID mapping. This is separately confirmed by a cheap preflight rejection. 500K can fit the conservative wire namespace but that is not a host-memory feasibility result.','- T=125000 at 1M also exceeds the old T cap. Raising T/A caps alone cannot repair the wire-ID issue. The persistent weight-buffer term absent from the old byte check is documented; the tested scaled cases remain under the unchanged byte admission.','- For the next EP64 correctness experiment, start at or below the observed T=6250/A=50000 point with the same H64/I128/bf16/top-k8 assumptions and guards. This is an engineering starting envelope, not proof that every smaller/differently skewed input succeeds. T=12500/A=100000 did not complete within the declared 300-second ns3 budget.\n- The feasible range on this host is limited to fully verified observed scales and this fixed synthetic workload. Unattempted 200K/500K points cannot be called OOM, feasible, or successful; different skew/locality/model bytes can change costs.','- Native lifecycle-ID allocation scans registered Jetty records per submission (`ub-function.cc:697-718`), creating a plausible quadratic host-cost path. No profiler-based percentage attribution or protocol throughput inference is claimed.\n- Future work should first investigate the measured slow phase using profiler evidence, then separately approve any event/task/Jetty or verifier indexing changes. No optimization proposal is implemented in this study.','','## Regressions and parity','', 'Small NoBalance and ChunkStreaming runs before/after instrumentation compare all emitted application/native/payload files byte-for-byte, excluding only the new optional metrics JSON. `parity-instrumented.json` records hashes. Full accepted Relay→Direct→Planner/NoBalance/PoC regression results are retained in `regressions/` and `regression-resource.json`. Default executor output and all submission/TA/chunk/group dependency behavior remain unchanged.','','Knowledge sources: repo-local OpenUSim plan/run/analyze skills, controlled-experiment-method, trace-observability and transport-channel cards; pinned native headers and application verifier source. The bespoke accepted application creates its own topology/TPs rather than using UbApp traffic generation.']
lines.insert(4, 'Measured starting host: cgroup memory limit '+host['memory_max']+' bytes; CPU quota/period '+host['cpu_max']+' microseconds; workspace free '+str(round(host['disk_free']/1024**3,2))+' GiB. Process-tree RSS guard 8GiB, cgroup guard 12GiB, ns3/verifier wall guard 300 seconds each. No swap was available. ns3 wall covers the whole executor process, including input/topology creation and payload/log flush, not just the event kernel.\n')
(OUT/'REPORT.md').write_text('\n'.join(lines)+'\n')
fig,axes=plt.subplots(1,2,figsize=(10,3.6),constrained_layout=True)
for mode in ['no-balancing','ultraep']:
 data=[r for r in attempted if r['mode']==mode]
 if not data:continue
 for phase,style in [('ns3','-'),('verify','--')]:
  points=[r for r in data if r[phase+'_wall_s'] is not None]
  axes[0].plot([r['requested_assignments'] for r in points],[r[phase+'_wall_s'] for r in points],style,marker='o',label=mode+'/'+phase)
  axes[1].plot([r['requested_assignments'] for r in points],[r[phase+'_peak_rss_kib']/1024**2 for r in points],style,marker='o',label=mode+'/'+phase)
  for r in points:
   if r[phase+'_status']!='PASS':axes[0].annotate('guard/failure',(r['requested_assignments'],r[phase+'_wall_s']),xytext=(-3,5),textcoords='offset points',fontsize=7,ha='right')
for ax in axes:ax.set_xlabel('Requested assignments (A=T×8)');ax.grid(alpha=.2);ax.legend(fontsize=7)
axes[0].set_ylabel('Host wall seconds (failed points censored)');axes[1].set_ylabel('Process peak RSS GiB');fig.savefig(OUT/'resource-curves.png',dpi=160);plt.close(fig)
print('capacity report and measured resource curves written')
